#include <cstddef>
#include <iostream>
#include <string>
#include <vector>

struct Param {
    std::string name;
    bool floating;  // a double or a float, rather than an integer, pointer, or reference
};

// The k-th integer argument, or the k-th floating-point one, counting from 0.
std::string system_v(bool floating, std::size_t k) {
    const std::vector<std::string> ints = {"rdi", "rsi", "rdx", "rcx", "r8", "r9"};
    if (floating) {
        return k < 8 ? "xmm" + std::to_string(k) : "stack";
    }
    return k < ints.size() ? ints[k] : "stack";
}

std::string apple_arm64(bool floating, std::size_t k) {
    if (k >= 8) {
        return "stack";
    }
    return (floating ? "d" : "x") + std::to_string(k);
}

void show(const std::string& function, const std::vector<Param>& params) {
    std::cout << function << '\n';
    std::size_t seen[2] = {0, 0};  // how many integers and how many doubles came before
    for (const Param& p : params) {
        std::size_t k = seen[p.floating]++;
        std::cout << "  " << p.name << ": " << system_v(p.floating, k) << ", "
                  << apple_arm64(p.floating, k) << '\n';
    }
}

int main() {
    show("order_cost(qty, px, fee_rate, fixed_fee_cents)",
         {{"qty", false}, {"px", true}, {"fee_rate", true}, {"fixed_fee_cents", false}});
    show("total8(a, b, c, d, e, f, g, h)",
         {{"a", false}, {"b", false}, {"c", false}, {"d", false},
          {"e", false}, {"f", false}, {"g", false}, {"h", false}});
    return 0;
}

