#include <cstdint>
#include <iostream>

// Each call records the address of its own local, then calls itself once more.
std::uintptr_t addr[3];

void walk(int depth) {
    int64_t level = depth;  // one local, which lives in this call's frame
    addr[depth] = reinterpret_cast<std::uintptr_t>(&level);
    if (depth < 2) {
        walk(depth + 1);
    }
}

int main() {
    walk(0);
    std::cout << std::boolalpha;
    std::cout << "deeper frames sit lower: " << (addr[1] < addr[0] && addr[2] < addr[1]) << '\n';
    std::cout << "bytes per frame: " << addr[0] - addr[1] << ' ' << addr[1] - addr[2] << '\n';
    return 0;
}

