#include <cstdint>
#include <iostream>
#include <memory>
#include <string>
#include <type_traits>
#include <utility>

struct Quote {
    double bid, ask;
};

struct Level {
    int64_t price_ticks, qty;
};

struct Tick {
    int64_t ts_ns;          // nanoseconds since midnight
    double bid, ask;        // prices
    double bid_sz, ask_sz;  // sizes
};

// System V x86-64 passes a class in registers only when it fits in 16 bytes
// and copying, moving, and destroying it are all trivial.
template <typename T>
constexpr bool in_registers() {
    return sizeof(T) <= 16 && std::is_trivially_copy_constructible_v<T> &&
           std::is_trivially_move_constructible_v<T> && std::is_trivially_destructible_v<T>;
}

template <typename T>
void report(const char* name) {
    std::cout << name << ": " << sizeof(T) << " bytes, "
              << (in_registers<T>() ? "registers" : "memory") << '\n';
}

int main() {
    report<Quote>("Quote");
    report<Level>("Level");
    report<std::pair<double, double>>("pair<double, double>");
    report<Tick>("Tick");
    report<std::unique_ptr<Tick>>("unique_ptr<Tick>");
    report<std::string>("string");
    return 0;
}

