// -O2
#include <chrono>
#include <cstddef>
#include <iomanip>
#include <iostream>
#include <vector>

// The exchange fee on one fill: 0.3 basis points of its notional, at least 1 cent.
[[gnu::noinline]] double fee_call(double notional) {  // always a real call
    double fee = notional * 0.00003;
    return fee < 0.01 ? 0.01 : fee;
}

double fee_inline(double notional) {  // small and visible, so -O2 inlines it
    double fee = notional * 0.00003;
    return fee < 0.01 ? 0.01 : fee;
}

double fees_call(const double* notional, std::size_t n) {
    double total = 0;
    for (std::size_t i = 0; i < n; ++i) {
        total += fee_call(notional[i]);
    }
    return total;
}

double fees_inline(const double* notional, std::size_t n) {
    double total = 0;
    for (std::size_t i = 0; i < n; ++i) {
        total += fee_inline(notional[i]);
    }
    return total;
}

int main() {
    const std::size_t n = 1'000'000;
    std::vector<double> notional(n + 50);
    for (std::size_t i = 0; i < notional.size(); ++i) {
        notional[i] = 250.0 * (1 + i % 400);  // fills from 250 to 100,000 dollars
    }
    double with_calls = 0, inlined = 0;
    auto t0 = std::chrono::steady_clock::now();
    for (int run = 0; run < 50; ++run) {
        with_calls += fees_call(notional.data() + run, n);
    }
    auto t1 = std::chrono::steady_clock::now();
    for (int run = 0; run < 50; ++run) {
        inlined += fees_inline(notional.data() + run, n);
    }
    auto t2 = std::chrono::steady_clock::now();
    using ms = std::chrono::duration<double, std::milli>;
    // std::cout << ms(t1 - t0).count() << " ms, " << ms(t2 - t1).count() << " ms\n";

    std::cout << std::fixed << std::setprecision(2);
    std::cout << "with calls: " << with_calls << '\n';
    std::cout << "inlined:    " << inlined << '\n';
    return 0;
}

